(3, 0, 'bug_report', 4, '{\"page_url\":\"https:\\/\\/mdgeek.top\\/index.php?page=ajouter_reparation\",\"user_agent\":\"Mozilla\\/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit\\/605.1.15 (KHTML, like Gecko) Version\\/18.5 Mobile\\/15E148 Safari\\/604.1\",\"description\":\"Il faudrait rajouter un module pour v\\u00e9rifier lorsque le prix est \\u00e0 01 message de confirmation pour demander si on est s\\u00fbre que le montant de la r\\u00e9paration est \\u00e0 z\\u00e9ro euro\"}', '2025-04-12 15:51:06'),
(4, 0, 'bug_report', 5, '{\"page_url\":\"https:\\/\\/mdgeek.top\\/index.php?page=statut_rapide&amp;id=562\",\"user_agent\":\"Mozilla\\/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit\\/605.1.15 (KHTML, like Gecko) Version\\/18.5 Mobile\\/15E148 Safari\\/604.1\",\"description\":\"J\\u2019ai un message me demandant de me connecter lorsque, j\\u2019appuie sur le bouton d\\u00e9marrer pour d\\u00e9marrer la t\\u00e2che\"}', '2025-04-12 15:53:12'),
