INSERT INTO `sms_templates` (`id`, `nom`, `contenu`, `statut_id`, `est_actif`, `created_at`, `updated_at`) VALUES
(1, 'Réparation en cours', 'Votre [APPAREIL_MODELE] est entre de bonnes mains ! Nos tournevis chauffent, les pixels tremblent. 🧑‍🔧\r\n🔍 Suivi : http://mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\nMaison du Geek – 08 95 79 59 33', 5, 1, '2025-04-09 23:53:13', '2025-06-21 12:52:51'),
(2, 'Réparation terminée', '[CLIENT_PRENOM], votre [APPAREIL_MODELE] est prêt ! Il vous attend pour retrouver une vie normale. 🥳\r\n🧾 Suivi : http://mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\nMaison du Geek – 08 95 79 59 33', 9, 1, '2025-04-09 23:53:13', '2025-06-21 12:53:29'),
(3, 'En attente de pièces', '📦 En attente de pièces\r\nVotre [APPAREIL_MODELE] attend sa livraison. Le livreur est en route à dos de modem. ⏳\r\n🚚 Suivi : http://Mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\nMaison du Geek – 08 95 79 59 33', 7, 1, '2025-04-09 23:53:13', '2025-06-20 23:18:04'),
(4, 'En attente de validation', 'Bonjour, [CLIENT_PRENOM], \r\nLe devis de votre [APPAREIL_MODELE] est disponible. \r\nConsultez votre devis detaillé ici :\r\n📄 http://Mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\nUne question ? Appelez-nous au 04 93 46 71 63\r\nMAISON DU GEEK', 6, 1, '2025-04-09 23:53:13', '2025-06-25 20:20:06'),
(5, 'Nouvelle reparation', '👋 Bonjour [CLIENT_PRENOM],\r\n🛠️ Nous avons bien reçu votre [APPAREIL_MODELE] et nos experts geeks sont déjà à l\'œuvre pour le remettre en état.\r\n🔎 Suivez l\'avancement de la réparation ici :\r\n👉 http://mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\n📞 Une question ? Contactez nous au 08 95 79 59 33\r\n🏠 Maison du GEEK 🛠️', 1, 1, '2025-04-09 23:53:27', '2025-06-21 12:51:20'),
(6, 'Nouvelle Intervention', '👋 Bonjour [CLIENT_PRENOM],\r\n🛠️ Nous avons bien reçu votre [APPAREIL_MODELE] et nos experts geeks sont déjà à l\'œuvre pour le remettre en état.\r\n🔎 Suivez l\'avancement de la réparation ici :\r\n👉 http://Mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\n💶 [PRIX]\r\n📞 Une question ? Contactez nous au 08 95 79 59 33\r\n🏠 Maison du GEEK 🛠️', 2, 1, '2025-04-10 02:15:50', '2025-06-20 23:20:21'),
(7, 'Nouvelle Commande', '  ', 3, 1, '2025-04-10 02:15:55', '2025-06-20 23:18:48'),
(8, 'En cours de diagnostique', 'Bonjour [CLIENT], votre devis de réparation pour [APPAREIL] d\'un montant de [PRIX] est prêt. Vous pouvez l\'accepter ou le refuser via ce lien: [LIEN_SUIVI]', 4, 1, '2025-04-10 02:16:00', '2025-06-21 22:54:03'),
(9, 'En attente d\'un responsable', 'Bonjour [CLIENT_PRENOM], votre dossier [REPARATION_ID] au sujet de votre [APPAREIL_MODELE] est en attente de validation par un responsable technique. Nous vous tenons informé très bientôt.\r\n📲 Suivi : http://Mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\nMaison du Geek – 08 95 79 59 33', 8, 1, '2025-04-10 02:16:06', '2025-06-20 23:18:00'),
(10, 'Réparation Annulée', 'Nous avons tout essayé pour sauver votre [APPAREIL_MODELE] ([APPAREIL_MARQUE]), mais pour des raisons techniques, nous avons dû annuler la réparation.\r\n📄 Détails : http://mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\nMaison du Geek – 08 95 79 59 33', 10, 1, '2025-04-10 02:16:12', '2025-06-21 12:51:51'),
(11, 'Restitué', '🎉 [CLIENT_PRENOM],\r\nTon [APPAREIL_MODELE] est de retour à la maison ! On espère qu’il est content 🤓\r\n💬 Laisse-nous un petit avis !\r\n⭐ https://g.page/r/Ce-HHwKZjezIEB0/review\r\n🏠 Maison du Geek\r\n📞 08 95 79 59 33\r\n', 11, 1, '2025-04-10 02:16:18', '2025-04-18 01:23:35'),
(12, 'Gardiennage', 'Bonjour [CLIENT_PRENOM] ! 👋\r\n\r\nVotre [APPAREIL_MODELE] vous attend depuis plusieurs jours! ⏰ \r\n\r\n⚠️ Important à savoir :\r\n• Frais de gardiennage : 5€/jour dès aujourd\'hui\r\n• Recyclage GRATUIT après 90 jours si non récupéré ♻️\r\n📍 Maison du Geek - Le Cannet\r\n📞 08 95 79 59 33\r\n📄 http://mdgeek.fr/suivi.php?id=[REPARATION_ID]', 12, 1, '2025-04-10 02:16:24', '2025-06-20 23:30:48'),
(13, 'Annulé', '😔 [CLIENT_PRENOM],\r\nOn a tout tenté pour réparer ton [APPAREIL_MODELE], mais pour raisons techniques, on a dû annuler la réparation.\r\n🔍 Détails : http://mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\n📞 Une Question ?  04 93 46 71 63\r\n🏠 Maison du Geek', 13, 1, '2025-04-10 02:16:29', '2025-06-20 23:17:25'),
(15, 'Terminé', '[CLIENT_PRENOM], on espère que ton [APPAREIL_MODELE] se porte comme un charme ! 😊 Aide nos Geeks avec un petit avis :\r\n⭐ https://g.page/r/Ce-HHwKZjezIEB0/review\r\n📲 Suivi : http://mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\nMaison du Geek – 08 95 79 59 33', 15, 1, '2025-04-10 02:16:51', '2025-06-21 12:50:41'),
(17, 'Relance client', 'Bonjour [CLIENT_PRENOM],\nVotre [APPAREIL_TYPE] [APPAREIL_MARQUE] [APPAREIL_MODELE] est réparé et attend votre visite à la boutique.\nMaison du Geek - 08 95 79 59 33', NULL, 1, '2025-04-23 00:14:29', '2025-04-23 00:14:29'),
(18, 'Relance Devis', '⏰ Rappel [CLIENT_PRENOM] !\r\n\r\nVotre [APPAREIL_MODELE] attend votre décision.\r\n📄 Confirmervotre devis ici :\r\n👉 http://mdgeek.fr/suivi.php?id=[REPARATION_ID]\r\n\r\n⚠️ IMPORTANT : Sans réponse de votre part sous 7 jours, votre appareil sera placé en gardiennage.\r\n\r\n📞 Questions ? 04 93 46 71 63\r\n🏠 Maison du Geek', NULL, 1, '2025-06-25 23:56:35', '2025-06-25 23:58:39'),
(20, 'Pièce détachée reçue', '🎉 Bonne nouvelle [CLIENT_PRENOM] ! 📦 La pièce pour votre [APPAREIL_TYPE] [APPAREIL_MARQUE] [APPAREIL_MODELE] est arrivée chez nous ! 🔧 Nos techniciens vont pouvoir commencer la réparation dès demain. 👉 Suivi en temps réel : http://mdgeek.fr/suivi.php?id=[REPARATION_ID] 📞 Une question ? 04 93 46 71 63 🏠 Maison du Geek', 20, 1, '2025-07-22 21:33:51', '2025-07-22 21:33:51');
