(7, 'Test', 'Test', 'haute', 'termine', '2025-04-01 01:09:44', '2025-04-01', '2025-04-11 03:05:22', 2, 1),
(18, 'Envoyer rib à Nkon', 'Envoyer rib pour remboursement', 'moyenne', 'termine', '2025-04-18 21:18:53', '2025-04-18', NULL, 5, 1),
(19, 'Imprimer document Comptable', 'Imprimer document comptable', 'moyenne', 'termine', '2025-04-18 22:45:23', NULL, '2025-04-28 22:21:37', 1, 1),
(20, 'Rayan', 'Pense a mettre a jours le dossier de la Togo pour ajouter la piece detaché au bons de commandes.\r\n( pour éviter les erreur lors de la commande, il faudrais que dans le nom de la piece, tu mette le nom de la piece en copier coller depuis chez volt )', 'moyenne', 'termine', '2025-04-18 23:26:24', NULL, NULL, 2, 1),
(23, 'Tes', 'T', 'moyenne', 'termine', '2025-04-28 19:20:49', NULL, NULL, 5, 1),
(25, 'Parler a Merlin', 'Dire a merlin qu\'il a oublier de clôturer le dossier du PC HP 14', 'moyenne', 'termine', '2025-07-15 19:39:39', NULL, NULL, 5, 1),
(26, 'Reconditionner iPhone 12', 'Reparer l\'iphone 12 pour l\'utiliser en tant que scanner d\'etiquette et terminal de paiement ( Carte bleue )', 'moyenne', 'termine', '2025-07-17 08:37:02', NULL, NULL, 2, 1),
(28, 'Vérifier batterie xiaomi Hs', 'Les xiaomi à refurb', 'moyenne', 'termine', '2025-07-17 20:49:25', NULL, NULL, 5, 2),
(29, 'nettoyer draisienne', 'Il faut nettoyer la draisienne.\r\nNettoyer le pneu et la fourche avant pour que ils apparaissent comme neuf.\r\nQuitte à mettre un coup de peinture\r\nsi jamais il faut mettre un coup de peinture, il faut demander à Benjamin ou au responsable Saber', 'moyenne', 'termine', '2025-07-22 11:06:31', NULL, NULL, 2, 1),
(31, 'Remonter la draisienne et envoyer devis', 'Batterie trop chère à réparer -\r\nEnvoyer un devis Remplacement batterie pour 129€', 'moyenne', 'termine', '2025-08-04 22:25:08', NULL, NULL, 2, 2),
(33, 'Décoller et mettre double face sur étiquette prix pneu', 'décoller les étiquettes de prix avec les pneus et mettre du double face', 'moyenne', 'termine', '2025-08-04 22:26:14', NULL, NULL, 2, 2),
(36, 'Nettoyer les trace d\'autocollant sur la porte', 'A l\'exterieur, sur la porte d\'entree du magasin, il y a des traec d\'autocollant.\r\nPrendre de l\'alcool, et une lame et retirer les trace, puis prendre du produit a vitre et nettoyer la porte d\'entree du magasin.', 'moyenne', 'termine', '2025-08-05 00:44:21', NULL, NULL, 2, 1),
(42, 'Demander a Sofien une prise de charge de xiaomi', 'je veut pas un port de charge, j\'ai besoin Dun bout de cable qui se branche a la trotinette\r\nEnregistre le Numero de sofien: +33 7 67 67 75 49', 'moyenne', 'termine', '2025-08-06 20:41:31', NULL, NULL, 2, 3),
(48, 'appeler cliente (periot cecile)', 'appeler la cliente pour avoir plus d\'information sur le telephone, quand a t\'il ete reparé etc', 'haute', 'termine', '2025-08-08 08:28:39', NULL, NULL, 2, 3),
(49, 'passer le balai', 'passer le balai dans tout le magasin ainsi que la serpillere', 'moyenne', 'termine', '2025-08-16 16:27:15', '2025-08-19', NULL, 2, 3),
(50, 'Expliquer a merlin de ne laisser ni miette ni canette dans le magasin', 'Je dois expliquer a merlin que il ne faut pas qu\'il laisse des miettes ou des canettes qu\'il a consommée dans le magasin a cause des cafard car samedi quand il est parti je me suis rendu compte qu\'il avait laissé 2 canette et des miettes de partout', 'haute', 'termine', '2025-08-16 16:33:52', '2025-08-19', NULL, 3, 3),
(51, 'Rangement Trottinette exterieur', 'Faire en sorte de ranger les trottinettes dehors guidon vers le coiffeur d\'en face collé a notre magasin et tout ça de façon esthetique par exemple du plus grand au plus petit', 'moyenne', 'termine', '2025-08-16 16:35:57', NULL, NULL, 2, 3),
(52, 'Bouteille d\'eau 50cl', 'Acheter bouteille d\'eau 50 cl sans exception (pas 33cl c\'est une horreur)', 'moyenne', 'termine', '2025-08-16 16:37:09', NULL, NULL, 2, 3),
(53, 'Ranger tiroir cable usb', 'Ranger les tiroirs ou les Cable Usb sont rangés.\r\nIl faut les ranger par catégorie', 'moyenne', 'termine', '2025-09-29 18:24:29', NULL, NULL, 2, 1),
(55, 'Installer disque frein dur Joyor qui est dehors', 'disque 145mmm', 'moyenne', 'termine', '2025-09-29 21:09:27', NULL, NULL, 6, 1),
(56, 'Remplacer lcd iscooter', 'verifier dans la cave si on a un lcd', 'moyenne', 'termine', '2025-09-29 21:10:20', NULL, NULL, 6, 1),
(57, 'Changer poignée xiaomi 4', 'Récupérer des poignées dans la cave et remplacer les poignées de la xiaomi', 'moyenne', 'termine', '2025-10-23 09:10:52', NULL, NULL, 3, 1),
(58, 'Changer les poignées de la xiaomi', 'Changer les poignées des deux xiaomi essentielles que nous avons reconditionné ce matin', 'moyenne', 'termine', '2025-10-23 09:15:19', NULL, NULL, 3, 1),
(59, 'Remettre toutes les Vis sur le plancher de la xiaomi', 'Le plancher de la xiaomi qui a été reconditionné par Adam ne comporte pas toutes les Vis. Merci De finaliser la réparation reparation et de combler tous les Vis Manquant', 'moyenne', 'termine', '2025-10-23 09:15:57', NULL, NULL, NULL, 1),
(60, 'Changer câble de frein Urban Glide', 'Changer le câble de frein de la Urban Glide, qui est en réparation, nous avons reçu des câbles de frein de 3 m ( Ils sont dans un sachet rangé à côté des plaquettes de frein )', 'moyenne', 'termine', '2025-10-23 09:18:36', NULL, NULL, NULL, 1),
(61, 'Nettoyer la trotinette pure', 'Adam doit nettoyer la trotinette pure', 'moyenne', 'termine', '2025-10-23 09:19:08', NULL, NULL, 7, 1),
(62, 'faire 2 chargeur DC', '1 chargeur est vendu avec la trotinette Beeper et 1 chargeur est pour notre stock', 'moyenne', 'termine', '2025-10-23 12:06:29', NULL, NULL, NULL, 1),
(63, 'Mettre vis pantalon iPhone 12', 'Mettre vis pantalon iPhone 12', 'moyenne', 'a_faire', '2025-10-31 11:52:28', NULL, NULL, 1, 1),
(64, 'Mettre annonce 13 pro max', 'Leboncoin', 'moyenne', 'a_faire', '2025-10-31 11:56:38', NULL, NULL, 1, 1);
